use std::process::Command;
use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;

fn run(bytes: &[u8]) -> [u8;4] {
    let out = Command::new("/workspace/dataset/test4_executable")
        .arg(OsStr::from_bytes(bytes)).output().expect("run");
    let s = String::from_utf8_lossy(&out.stdout);
    let mut r = [9u8;4];
    for (i,l) in s.lines().enumerate() { if i<4 { r[i] = if l.trim()=="1" {1} else {0}; } }
    r
}

// xorshift rng
struct R(u64);
impl R { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }

fn main(){
    let mut rng = R(0x12345678deadbeef);
    let mut bad = 0;
    // Fuzz: random byte strings, lengths 1..=300, no NUL (impossible in argv)
    for iter in 0..4000u32 {
        let len = 1 + (rng.n() % 300) as usize;
        let mut v = Vec::with_capacity(len);
        for _ in 0..len {
            let b = (rng.n() % 255) as u8 + 1; // 1..=255
            v.push(b);
        }
        let r = run(&v);
        let expect = if v.len() >= 1 && v.len() <= 255 {1} else {0};
        if r[0] != expect {
            bad += 1;
            println!("MISMATCH iter={} len={} expect_line1={} got={:?}", iter, v.len(), expect, r);
            println!("  hex: {}", v.iter().map(|b| format!("{:02x}",b)).collect::<Vec<_>>().join(""));
            if bad > 8 { break; }
        }
    }
    println!("random fuzz done, mismatches={}", bad);
}
RS
